"""Heavy Combo split into single cuts + recovery, each generated by local H3 fl2va
between two approved pixel key poses. Segments with an existing job.json are skipped.

    py tools/run_h3_heavy_segments.py [segment ...]
"""
import json,sys,time,urllib.parse
from pathlib import Path
from PIL import Image
from comfy_minimax import api,upload,build_graph

ROOT=Path(__file__).resolve().parent.parent
POSES=ROOT/'art_source/reference/poses'
OUT=ROOT/'art_source/minimax/heavy_combo_seg_v01'
HOST='127.0.0.1:8189'
SEED=20261015

STYLE=('2D pixel art side-scrolling action game animation of the same small yellow calf warrior as the supplied images: '
       'brown shorts, brown hooves, a short tail with a dark tuft, holding a large steel-gray greatsword. '
       'The greatsword is one rigid straight blade with a single light edge line; it keeps exactly the same shape, width and length '
       'in every frame and moves as one solid object gripped in both hands. ')
CAMERA=(' The calf stays in right-facing side profile, entirely inside the frame, with constant body size. '
        'Locked orthographic side camera, constant framing, crisp pixel shapes, the original limited palette, '
        'readable hand-animated key poses. A uniform solid pure green background fills the entire frame throughout.')
SEGMENTS={
    'cut1':('idle_tail','slash1_end',39,
            'He bends his knees and draws the sword back behind his shoulder, then steps forward and swings the blade '
            'in one fast horizontal arc, ending with arms extended and the blade pointing straight forward at chest height.'),
    'cut1_recover':('slash1_end','idle_tail',22,
            'Holding the extended forward slash for a moment, he lets the weight of the sword settle, draws the front foot back '
            'and returns calmly to his ready stance with the blade angled up in front of him.'),
    'cut2':('slash1_end','slash3_end',39,
            'From the extended forward slash he lifts the sword high above his head with both hands, then brings it down '
            'in one heavy vertical cleave, leaning forward with bent knees and ending with the blade low in front of him.'),
}

def green_canvas(pose:str,dst:Path)->Path:
    im=Image.open(POSES/f'niulai_{pose}_native.png').convert('RGBA').resize((768,768),Image.Resampling.NEAREST)
    bg=Image.new('RGBA',im.size,(0,255,0,255));bg.alpha_composite(im);bg.convert('RGB').save(dst);return dst

def run(name:str)->None:
    first,last,frames,motion=SEGMENTS[name]
    d=OUT/name;d.mkdir(parents=True,exist_ok=True)
    if (d/'job.json').exists():print('skip',name,'(job.json exists)');return
    prompt=STYLE+motion+CAMERA;(d/'prompt.txt').write_text(prompt,encoding='utf-8')
    f=upload(HOST,green_canvas(first,d/f'first_{first}.png'));l=upload(HOST,green_canvas(last,d/f'last_{last}.png'))
    graph=build_graph(prompt,768,768,frames,SEED,f'heavy_combo_seg_v01_{name}',f,l,8)
    (d/'workflow_api.json').write_text(json.dumps(graph,indent=2),encoding='utf-8')
    pid=json.loads(api(HOST,'/prompt',json.dumps({'prompt':graph}).encode(),{'Content-Type':'application/json'}))['prompt_id']
    job={'prompt_id':pid,'mode':'fl2va_first_last_keypose','reference_motion':'Sword_Heavy_Combo','reference_video_fed_to_model':False,
         'first_pose':first,'last_pose':last,'seed':SEED,'fps':24,'requested_frames':frames,'size':[768,768],'steps':8}
    (d/'job.json').write_text(json.dumps(job,indent=2),encoding='utf-8')
    print('QUEUED',name,pid,flush=True);t0=time.time()
    while True:
        hist=json.loads(api(HOST,'/history/'+pid))
        if pid in hist:entry=hist[pid];break
        time.sleep(5)
    (d/'history.json').write_text(json.dumps(entry,indent=2),encoding='utf-8')
    if entry.get('status',{}).get('status_str')=='error':raise SystemExit(f'{name} failed; see history.json')
    fr=d/'frames';fr.mkdir(exist_ok=True);n=0
    for node in entry['outputs'].values():
        for kind in ('images','videos','gifs'):
            for o in node.get(kind,[]):
                data=api(HOST,'/view?'+urllib.parse.urlencode({k:o[k] for k in ('filename','subfolder','type')}))
                if o['filename'].lower().endswith('.png'):n+=1;(fr/f'{n:04d}.png').write_bytes(data)
                else:(d/('generated'+Path(o['filename']).suffix)).write_bytes(data)
    job.update(elapsed_seconds=round(time.time()-t0,2),saved_frames=n,status='generated_pending_visual_review')
    (d/'job.json').write_text(json.dumps(job,indent=2),encoding='utf-8')
    print('DONE',name,n,job['elapsed_seconds'],flush=True)

if __name__=='__main__':
    api(HOST,'/system_stats')
    for s in sys.argv[1:] or SEGMENTS:run(s)
